// ===== CONFIG — edit these =====
const STALE_DAYS = 30;              // "inactive" threshold for licensed users
const DEFAULT_SEAT_PRICE = 12;      // USD/month fallback when SKU not in the map
const SEAT_PRICES = {               // your real per-seat cost per month (partner pricing)
  'O365_BUSINESS_ESSENTIALS': 6,
  'O365_BUSINESS_PREMIUM': 22,
  'SPB': 22,                        // Microsoft 365 Business Premium
  'SPE_E3': 36,
  'ENTERPRISEPACK': 23,             // Office 365 E3
  'EXCHANGESTANDARD': 4,
};
// friendly names for common SKUs
const SKU_NAMES = {
  'O365_BUSINESS_ESSENTIALS': 'M365 Business Basic',
  'O365_BUSINESS_PREMIUM': 'M365 Business Standard',
  'SPB': 'M365 Business Premium',
  'SPE_E3': 'Microsoft 365 E3',
  'ENTERPRISEPACK': 'Office 365 E3',
  'EXCHANGESTANDARD': 'Exchange Online P1',
};
// ===== END CONFIG =====

const skus = $('Fetch Subscribed SKUs').first().json.value || [];
const users = $('Fetch Users and Licenses').first().json.value || [];

const now = new Date();
const skuById = {};
for (const s of skus) skuById[s.skuId] = s;

const prettySku = (part) => SKU_NAMES[part] || part;
const priceOf = (part) => SEAT_PRICES[part] ?? DEFAULT_SEAT_PRICE;

// 1) Unassigned paid seats per SKU
const unassigned = [];
let unassignedWaste = 0;
for (const s of skus) {
  const paid = s.prepaidUnits?.enabled ?? 0;
  const used = s.consumedUnits ?? 0;
  const free = paid - used;
  if (free > 0) {
    const waste = free * priceOf(s.skuPartNumber);
    unassignedWaste += waste;
    unassigned.push({ sku: prettySku(s.skuPartNumber), paid, used, free, waste });
  }
}

// 2) Licensed but disabled users; 3) licensed users with stale sign-in
const disabledLicensed = [];
const staleLicensed = [];
let disabledWaste = 0;
let staleWaste = 0;
let signInDataAvailable = false;

for (const u of users) {
  const lic = u.assignedLicenses || [];
  if (lic.length === 0) continue;
  const licCost = lic.reduce((sum, l) => {
    const s = skuById[l.skuId];
    return sum + priceOf(s ? s.skuPartNumber : '');
  }, 0);
  const licNames = lic.map(l => prettySku(skuById[l.skuId]?.skuPartNumber || 'unknown')).join(', ');

  if (u.accountEnabled === false) {
    disabledWaste += licCost;
    disabledLicensed.push({ name: u.displayName, upn: u.userPrincipalName, licenses: licNames, cost: licCost });
    continue; // don't double-count in stale list
  }

  const lastSignIn = u.signInActivity?.lastSignInDateTime;
  if (u.signInActivity) signInDataAvailable = true;
  if (lastSignIn) {
    const days = Math.floor((now - new Date(lastSignIn)) / 86400000);
    if (days >= STALE_DAYS) {
      staleWaste += licCost;
      staleLicensed.push({ name: u.displayName, upn: u.userPrincipalName, licenses: licNames, days, cost: licCost });
    }
  }
}

staleLicensed.sort((a, b) => b.days - a.days);
const totalWaste = unassignedWaste + disabledWaste + staleWaste;

// ---- build HTML report ----
const esc = (x) => String(x ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;');
const table = (headers, rows) => rows.length
  ? `<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;font-family:Arial;font-size:13px"><tr>${headers.map(h => `<th style=\"background:#f0f0f0;text-align:left\">${h}</th>`).join('')}</tr>${rows.join('')}</table>`
  : '<p style="color:green;font-family:Arial">✔ Nothing found — clean.</p>';

const html = `
<div style="font-family:Arial;max-width:760px">
<h2>Microsoft 365 License Reconciliation — ${now.toISOString().slice(0, 10)}</h2>
<p style="font-size:15px">Estimated monthly waste: <b style="color:${totalWaste > 0 ? '#c0392b' : 'green'}">$${totalWaste.toFixed(0)}</b> (prices from your config; edit them in the Analyze node)</p>
<h3>1. Paid seats not assigned to anyone (${unassigned.length} SKUs, ~$${unassignedWaste.toFixed(0)}/mo)</h3>
${table(['SKU', 'Paid', 'Assigned', 'Unused', '$/mo'], unassigned.map(r => `<tr><td>${esc(r.sku)}</td><td>${r.paid}</td><td>${r.used}</td><td><b>${r.free}</b></td><td>$${r.waste.toFixed(0)}</td></tr>`))}
<h3>2. Disabled accounts still holding licenses (${disabledLicensed.length} users, ~$${disabledWaste.toFixed(0)}/mo)</h3>
${table(['User', 'UPN', 'Licenses', '$/mo'], disabledLicensed.map(r => `<tr><td>${esc(r.name)}</td><td>${esc(r.upn)}</td><td>${esc(r.licenses)}</td><td>$${r.cost.toFixed(0)}</td></tr>`))}
<h3>3. Licensed users inactive ${STALE_DAYS}+ days (${staleLicensed.length} users, ~$${staleWaste.toFixed(0)}/mo)</h3>
${signInDataAvailable ? '' : '<p style="color:#e67e22">⚠ Sign-in data unavailable (requires Entra ID P1 and AuditLog.Read.All permission).</p>'}
${table(['User', 'UPN', 'Licenses', 'Days inactive', '$/mo'], staleLicensed.map(r => `<tr><td>${esc(r.name)}</td><td>${esc(r.upn)}</td><td>${esc(r.licenses)}</td><td><b>${r.days}</b></td><td>$${r.cost.toFixed(0)}</td></tr>`))}
<p style="color:#888;font-size:12px">Generated by n8n · users scanned: ${users.length} · SKUs: ${skus.length}</p>
</div>`;

return [{
  json: {
    reportDate: now.toISOString().slice(0, 10),
    totalWaste: Math.round(totalWaste),
    unassignedCount: unassigned.reduce((s, r) => s + r.free, 0),
    disabledCount: disabledLicensed.length,
    staleCount: staleLicensed.length,
    subject: `M365 licenses: ~$${totalWaste.toFixed(0)}/mo wasted · ${disabledLicensed.length} disabled w/ licenses · ${staleLicensed.length} inactive`,
    html,
  },
}];
